-- Link-Texte als Handlung formulieren; nur system-Zeilen, Admin-Overrides bleiben unangetastet.
UPDATE "mail_templates" SET "body" = replace(replace(replace(replace(body, $a$Keine Termin-Mails mehr{{#multiple}} für {{name}}{{/multiple}}:$a$, $b$Termin-Mails{{#multiple}} für {{name}}{{/multiple}} abbestellen:$b$), $a$Keine Termin-Mails mehr für alle Mitglieder dieser Adresse:$a$, $b$Termin-Mails für alle Mitglieder dieser Adresse abbestellen:$b$), $a$Keine Termin-Mails mehr:$a$, $b$Termin-Mails abbestellen:$b$), $a$„Keine Termin-Mails mehr“$a$, $b$„Termin-Mails abbestellen“$b$) WHERE "variant" = 'system' AND "key" IN ('event-created', 'event-updated', 'event-cancelled', 'event-uncancelled', 'event-mail-info');
